consts.type:
∀ {K : Type u} {V : Type v} [inst : DivisionRing K] [inst_1 : AddCommGroup V] [inst_2 : Module K V] {ι : Type u_1}
  [inst_3 : Fintype ι] [FiniteDimensional K V] {b : ι → V},
  LinearIndependent K b → Fintype.card ι = Module.finrank K V → Submodule.span K (Set.range b) = ⊤

nodes.ty:
∀ {K : Type u_1} {V : Type u_2} [inst : DivisionRing K] [inst_1 : AddCommGroup V] [inst_2 : Module K V] {ι : Type}
  [inst_3 : Fintype ι] [FiniteDimensional K V] {b : ι → V},
  LinearIndependent K b → Fintype.card ι = finrank K V → span K (Set.range b) = ⊤

∀ {R R₂ : Type u_1} {M M₂ : Type u_2} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]
  [inst_3 : Semiring R₂] {σ₁₂ : R →+* R₂} [inst_4 : AddCommMonoid M₂] [inst_5 : Module R₂ M₂] {s : Set M}
  [inst_6 : RingHomSurjective σ₁₂] (f : M →ₛₗ[σ₁₂] M₂), span R₂ (⇑f '' s) = map f (span R s)
